#!/bin/bash
# Cross-build the pinsel_core wheel for Windows (x86_64-pc-windows-gnu) on
# Linux, with zig as the linker (no MSVC, no xwin licence prompt). The abi3
# import library is generated by pyo3's generate-import-lib feature.
#
#   bash rust/harness/build_windows.sh        (from the root of a clone)
#
# Result: rust/target/wheels/pinsel_core-*-cp310-abi3-win_amd64.whl
# Tested 2026-11-27: installs on Windows CPython 3.11; quickstart paints the
# same pixels as the Linux wheel (540,000 of 540,000).
set -e
source ~/.cargo/env
ROOT=$(pwd)
[ -d "$ROOT/.venv-win" ] || { python3 -m venv "$ROOT/.venv-win" && "$ROOT/.venv-win/bin/pip" -q install maturin ziglang; }
source "$ROOT/.venv-win/bin/activate"          # puts zig (python -m ziglang) where maturin finds it
rustup target add x86_64-pc-windows-gnu >/dev/null
cd rust/pinsel-py
maturin build --release --target x86_64-pc-windows-gnu --zig -F pyo3/generate-import-lib 2>&1 | tail -3
